+        } else {
+            VersionReq::parse(range, Ecosystem::Npm)
+        };
+        match requirement {
+            Ok(requirement) => Ok(if requirement.matches(version)? {
+                Coverage::Covers
+            } else {
+                Coverage::DoesNotCover
+            }),
+            Err(_) => Ok(Coverage::Unknown),
+        }
